"""Additional original definitions for the mechanism chapters 01–07.

Data only; this module performs no commands or file operations.
"""

GLOSSARY = [
    ('Канонические байты объекта', 'Последовательность, по которой вычисляют имя объекта Git: тип, пробел, длина содержимого в десятичной записи, нулевой байт и само содержимое. Физическое сжатие может меняться без изменения этой последовательности.'),
    ('Коллизия хеша', 'Совпадение результата хеш-функции для разных входных байтов. Ограниченная длина результата делает коллизии математически возможными; проверка хеша сама по себе не устанавливает автора данных.'),
    ('Заголовок объекта Git', 'Часть канонического представления перед содержимым: например blob 6 и нулевой байт для шестибайтового файла. Это не тот же заголовок, который использует физическая запись объекта внутри pack.'),
    ('Запись дерева Git', 'Байтовая связь режима, одного компонента имени и идентификатора объекта. Полный путь получается проходом вложенных деревьев, а имя не хранится внутри blob.'),
    ('Gitlink', 'Запись дерева с режимом 160000, указывающая на коммит другого репозитория, обычно подмодуля. Она фиксирует выбранную версию, но не помещает все файлы подмодуля в родительский blob.'),
    ('База объектов Git', 'Логическое хранилище blob, tree, commit и tag, читаемых по идентификаторам. Физически объекты могут быть отдельными сжатыми файлами или записями упаковок.'),
    ('Plumbing', 'Низкоуровневые команды Git, отдельно читающие или создающие объекты и служебные структуры. Например commit-tree создаёт объект, но не выполняет всю обычную процедуру пользовательского commit.'),
    ('Porcelain', 'Пользовательский уровень команд и предусмотренных машинных форматов Git. Он объединяет низкоуровневые действия в удобные операции; слово само по себе не означает графический интерфейс.'),
    ('Нулевой разделитель', 'Байт NUL, которым можно отделять имена путей в машинном потоке, потому что внутри допустимого имени файла этого байта нет. Он позволяет не путать перевод строки в имени с концом записи.'),
    ('Байтовое имя пути', 'Сохранённая последовательность байтов имени, которая может отличаться от видимого отображения. Unicode, регистр и ограничения конкретной файловой системы влияют на извлечение дерева в рабочие файлы.'),
    ('DIRC', 'Четырёхбайтовая ASCII-сигнатура в начале файла индекса Git; историческое сокращение directory cache. За ней расположены версия формата и число записей.'),
    ('Cache entry', 'Запись индекса для пути: режим, имя объекта содержимого, стадия, флаги и вспомогательные сведения файловой системы. При конфликте один путь может иметь несколько записей разных стадий.'),
    ('Версия индекса Git', 'Номер двоичного формата служебного файла индекса. В Git 2.43.0 поддерживаются версии 2, 3 и 4; правила флагов, хранения путей и выравнивания различаются.'),
    ('Контрольная сумма индекса', 'Хеш предшествующих байтов файла индекса, записанный в его конце. Он обнаруживает несоответствие записи, но не доказывает равенство рабочего дерева подготовленному состоянию.'),
    ('Network byte order', 'Сетевой порядок байтов, при котором старший байт многобайтового числа хранится первым. Так записаны числовые поля заголовка и основных структур индекса Git.'),
    ('Racy Git', 'Случай, когда изменение файла той же длины может оказаться неразличимым по дешёвым временным метаданным. Git должен распознать опасную запись и уточнить содержимое, а не довериться одному совпадению размера и mtime.'),
    ('Cache-tree', 'Необязательное расширение TREE в индексе, запоминающее соответствие участков таблицы путей готовым объектам деревьев. Оно ускоряет построение снимка и пересчитывается при изменении соответствующих записей.'),
    ('REUC', 'Сигнатура расширения resolve undo в индексе. Оно может сохранить прежние конфликтные стадии после подготовки разрешённого пути, чтобы конфликт можно было восстановить для повторного решения.'),
    ('Split index', 'Разделённое представление индекса: общая крупная основа и отдельный набор изменений. Оно уменьшает объём переписывания служебной таблицы, не создавая отдельную ветку истории.'),
    ('Sparse index', 'Разреженный индекс, способный представить невыбранный подкаталог записью дерева вместо перечисления каждого его файла. Это оптимизация рабочей выборки, а не потеря файлов из сохранённого коммита.'),
    ('Skip-worktree', 'Признак записи индекса, используемый в том числе для путей вне разреженной рабочей выборки. Он не является универсальным обещанием игнорировать все будущие изменения личного конфигурационного файла.'),
    ('Assume-unchanged', 'Подсказка Git о предполагаемой неизменности рабочего файла для некоторых проверок метаданных. Она не удаляет путь из индекса и не заменяет правила отслеживания или отдельную локальную конфигурацию.'),
    ('Index lock', 'Файл блокировки обновления индекса, обычно index.lock. Он помогает исключить одновременную запись несколькими процессами; забытая после сбоя блокировка и активная блокировка требуют разного обращения.'),
    ('Git common directory', 'Общий служебный каталог связанных worktree: там расположены общие объекты, большинство ссылок и общие настройки. У каждого рабочего дерева при этом отдельны HEAD и индекс.'),
    ('Условное обновление ссылки', 'Замена значения ссылки только при совпадении текущего идентификатора с ожидаемым старым. Такой договор позволяет обнаружить конкурентное изменение вместо его молчаливой перезаписи.'),
    ('Топологический порядок', 'Представление графа, уважающее родительские зависимости. В журнале Git потомки показываются до своих ещё показываемых родителей; независимые вершины могут иметь несколько допустимых порядков.'),
    ('Симметрическая разность коммитов', 'Коммиты, достижимые только из одной из двух выбранных вершин. У log и rev-list её обычно задают тремя точками; у diff тот же синтаксис задаёт другой способ выбора сравниваемых снимков.'),
    ('Историческое значение ссылки', 'Значение, записанное в локальном reflog для прежнего момента или порядкового номера. Оно описывает движение ссылки на этой машине, а не обязательно родителя текущего коммита.'),
    ('Проверка типа ревизии', 'Явное требование получить объект подходящего типа, например через ^{commit} или ^{tree}. Оно отличает сам объект аннотированной метки от коммита или дерева под ней.'),
    ('Упрощение истории пути', 'Правила обхода и показа, которые сокращают граф при поиске изменений выбранного файла. Невидимый в таком выводе merge мог существовать в полном графе и влиять на происхождение других путей.'),
    ('Pickaxe', 'Семейство средств поиска коммитов по свойствам изменённых строк. В git log параметр -S исследует изменение количества вхождений строки, а -G — соответствие строк заплатки регулярному выражению.'),
    ('Нулевой диапазон hunk', 'Сторона участка заплатки с числом строк 0. Она обозначает границу вставки или удаления, а не существующую строку с нулевым номером.'),
    ('Myers diff', 'Алгоритм сопоставления последовательностей для построения различий. Практическое представление может дополнительно зависеть от эвристик границ и ограничений затрат.'),
    ('Patience diff', 'Алгоритм различий, использующий однозначные редкие строки как опорные точки. Он может удобнее показать перестановки похожих блоков, но не устанавливает человеческий замысел изменения.'),
    ('Histogram diff', 'Алгоритм сопоставления, учитывающий низкую частоту общих строк. Он меняет выбранное представление заплатки, сохраняя те же исходные и конечные данные.'),
    ('Textconv', 'Преобразование файла в удобное для просмотра текстовое представление diff. Оно может быть односторонним и потому не обязано порождать заплатку, восстанавливающую исходные бинарные данные.'),
    ('Criss-cross merge', 'Перекрёстная история, в которой независимые слияния линий приводят к нескольким лучшим общим предкам. Выбор одного предка только по дате не описывает корректное основание последующего слияния.'),
    ('Виртуальная база слияния', 'Вычисленное объединённое дерево подходящих общих оснований, используемое стратегией при сложном графе. Оно не обязано соответствовать одному пользовательскому коммиту или ветке.'),
    ('Стратегия ort', 'Алгоритм Git для трёхстороннего слияния двух голов, учитывающий переименования и при необходимости объединяющий общие основания. Его результат ещё требует проверки смысла программы.'),
    ('Rename/delete conflict', 'Конфликт между переименованием исходного пути на одной стороне и его удалением на другой. Решение должно определить существование и назначение пути, а не только убрать текстовые маркеры.'),
    ('AUTO_MERGE', 'Служебная ссылка на дерево первоначального рабочего результата ort при некоторых конфликтах. Сравнение с ним помогает увидеть правки разрешения, но не заменяет стадии исходных сторон и не является готовым коммитом.'),
    ('Rerere', 'Повторное использование записанного разрешения конфликта. Оно экономит редактирование знакомой формы, но не доказывает, что прежнее решение подходит новому прикладному контексту.'),
]
